// Navigation stores only view coordinates, never manuscript snapshots.
function createViewHistory(browser=null){
 let entries=[],cursor=-1,nextId=0,moving=false,session=browser?.newSession();
 const stateFor=id=>({...browser.history.state,spiritView:{session,id}});
 const activate=index=>{cursor=index;return structuredClone(entries[cursor].view)};
 const api={
  record(view){
   const v=structuredClone(view);if(cursor>=0&&JSON.stringify(entries[cursor].view)===JSON.stringify(v))return;
   entries=entries.slice(0,cursor+1);const entry={id:nextId++,view:v};entries.push(entry);if(entries.length>100)entries.shift();cursor=entries.length-1;
   if(browser)browser.history[entry.id===0?'replaceState':'pushState'](stateFor(entry.id),'');
  },
  move(delta){const next=cursor+delta;if(moving||next<0||next>=entries.length)return null;if(browser){moving=true;browser.history.go(delta);return null}return activate(next)},
  reset(){entries=[];cursor=-1;nextId=0;moving=false;if(browser){session=browser.newSession();browser.history.replaceState(stateFor(null),'')}},
  get back(){return cursor>0},get forward(){return cursor>=0&&cursor<entries.length-1}
 };
 if(browser)browser.listen(event=>{
  moving=false;const marker=event.state?.spiritView;if(!marker)return;
  const index=marker.session===session?entries.findIndex(entry=>entry.id===marker.id):-1;
  // Previous accounts, reloads and routes older than the in-memory limit cannot restore a screen.
  if(index<0){if(entries[cursor])browser.history.replaceState(stateFor(entries[cursor].id),'');return}
  browser.onNavigate(activate(index));
 });
 return api;
}
