function languageSaveStatus(lang){const current=doc().paragraphDrafts?.[selectedBlock]?.[lang];const saved=store.savedState()?.documents[key()]?.paragraphDrafts?.[selectedBlock]?.[lang];return typeof saved==='string'&&current===saved?(store.kind==='supabase'?'클라우드 저장됨':'파일 저장됨'):''}
async function saveProject(scope=null){
 if(projectSaving)return toast('저장이 끝난 후 다시 눌러주세요.');projectSaving=true;
 const revision=editRevision,language=scope?.language,label=language==='ko'?'한국어':language==='en'?'영어':'전체 대본';
 const destination=store.kind==='supabase'?'클라우드':'파일';
 const buttons=['save-file','save-ko','save-en'].map(id=>$('#'+id)).filter(Boolean);buttons.forEach(b=>b.disabled=true);
 try{
  let result;if(scope){const d=data.documents[scope.collectionId+'/'+scope.chapterId];if(!d)throw Error('저장할 대본을 확인하세요.');if((d.paragraphRevision||0)!==(store.savedState()?.documents[scope.collectionId+'/'+scope.chapterId]?.paragraphRevision||0))throw Error('문단을 나누거나 합친 뒤에는 전체 저장을 눌러 주세요.');result=await store.saveDoc(scope.collectionId,scope.chapterId,d,{language,blockIndex:scope.blockIndex,state:data})}else result=await store.saveAll(data);
  $('#save').textContent=scope?`${label} ${destination} 저장됨`:revision===editRevision?`${destination} 저장됨`:'새 수정 있음 · 저장 필요';
  for(const lang of ['ko','en']){const status=$('#saved-'+lang);if(status)status.textContent=languageSaveStatus(lang)}
  toast(result?.warning||`${label}${scope?' 문단':''}을 ${destination}에 저장했습니다.`);
 }catch(e){toast(e.message||'파일 저장에 실패했습니다.')}finally{projectSaving=false;buttons.forEach(b=>b.disabled=false)}
}
$('#save-file').onclick=()=>saveProject();
const countLabel=s=>`${s.collections.length}개 발표 · ${s.collections.reduce((n,c)=>n+c.chapters.length,0)}개 장`;
$('#load-file').onclick=()=>storageDialog('대본 불러오기','불러오기 전 현재 대본은 브라우저에 임시 백업됩니다.',[
 {label:store.kind==='supabase'?'클라우드 저장본':'프로젝트 저장본',primary:true,action:async()=>{try{const v=await store.fetchSaved();if(!v.exists)return toast('프로젝트 저장본이 없습니다. 먼저 저장을 눌러주세요.');storageDialog(store.kind==='supabase'?'클라우드 저장본':'프로젝트 저장본',`${new Date(v.savedAt).toLocaleString('ko-KR')} · ${countLabel(v.state)}`,[{label:'이 저장본 불러오기',primary:true,action:()=>{store.acceptSaved?.(v);return applyState(structuredClone(v.state),'replace')}}])}catch(e){toast(e.message)}}},
 {label:'백업 파일 선택',action:()=>$('#import-file').click()},
 ...(legacyOffer||(store===localServerStore&&legacyFromBrowser())?[{label:'기존 대본 가져오기',action:importLegacy}]:[]),
 ...(data.trash?.length?[{label:'최근 삭제 복원',action:()=>{try{const next=restoreDeleted(data);const t=data.trash.at(-1);data=next;colId=t.kind==='collection'?t.collection.id:t.collectionId;homeView=false;libraryView=true;persist();$('#storage-dialog').close();render();toast('삭제한 항목을 복원했습니다.')}catch(e){toast(e.message)}}}]:[]),
 {label:'직전 불러오기 취소',action:async()=>{try{const previous=toState(store.beforeRestore?await store.beforeRestore():JSON.parse(localStorage.getItem('spirit-before-restore')||'null'));if(!previous)return toast('이전 대본이 없습니다.');applyState(previous,'replace')}catch{toast('이전 대본을 읽지 못했습니다.')}}}]);
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>(store.kind==='supabase'?22000000:10000000))throw Error('백업 파일이 너무 큽니다.');const payload=JSON.parse(await file.text());const s=toState(payload.format==='spirit-vault-v1'&&store.importBackup?await store.importBackup(payload):payload);if(!s)throw Error('SPIRIT 백업 파일이 아닙니다.');storageDialog('백업 파일 불러오기',`${file.name} · ${countLabel(s)}. 합치기는 지금 대본을 그대로 두고 없는 발표·장·기본 원고만 더합니다. 바꾸기 전 현재 대본은 임시 백업됩니다.`,[{label:'기존 대본에 추가',primary:true,action:()=>applyState(s,'merge')},{label:'전체 바꾸기',action:()=>applyState(s,'replace')}])}catch(e){toast(e.message||'백업 파일을 읽지 못했습니다.')}};
