async function restoreProjectOnStart(){const startingRevision=editRevision;try{const v=await store.fetchSaved();if(!v.exists||data.collections.length||startingRevision!==editRevision)return;if(v.legacy){if(!legacyOffer){legacyOffer=v.state;if(libraryView)render()}return}data=structuredClone(v.state);await store.cache(data);render();$('#save').textContent='프로젝트 저장본 복원됨'}catch{}}
