const currentReading=()=>{const cs=getComputedStyle(document.documentElement);return {size:parseFloat(cs.getPropertyValue('--script-size')),leading:parseFloat(cs.getPropertyValue('--script-leading'))}};
function applyReading(){const root=document.documentElement.style;root.removeProperty('--script-size');root.removeProperty('--script-leading');if(reading){root.setProperty('--script-size',reading.size+'px');root.setProperty('--script-leading',reading.leading)}const v=currentReading();$('#reading-size').textContent=v.size;$('#reading-leading').textContent=v.leading.toFixed(2);$$('.reading-out-size').forEach(o=>o.textContent=v.size);$$('.reading-out-leading').forEach(o=>o.textContent=v.leading.toFixed(2))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-reading]');if(!b)return;const [k,d]=b.dataset.reading.split(':'),[min,max,step]=k==='size'?[15,21,1]:[1.6,2.1,.05];reading={...currentReading(),...reading};reading[k]=Math.round(Math.min(max,Math.max(min,reading[k]+step*d))*100)/100;try{localStorage.setItem('spirit-reading-prefs',JSON.stringify(reading))}catch{}applyReading()});
$('#reading-reset').onclick=()=>{reading=null;try{localStorage.removeItem('spirit-reading-prefs')}catch{}applyReading()};$('#reading-prefs').addEventListener('toggle',applyReading);applyReading();

